// Priority order: S1, S2, S4, S6, S5 (S3 has no acceptance criteria).
// S1 (8) → left 5 · S2 skipped (S4 not taken yet) · S4 (3) → left 2 · S6 (5) does not fit · S5 (2) → left 0.
const SPRINT = { taken: ['S1', 'S4', 'S5'], points: 13, needsRefinement: ['S3'] };

// R1: 5 and 8 are neighbours → 8. R2: 2 and 13 are far apart → An and Dung (2), then Binh (13) explain. R3: 20.
const POKER = {
  R1: 8,
  R2: 'NO_CONSENSUS',
  R2explain: ['An', 'Dung', 'Binh'],
  R3: 20,
  invest: { I1: 'Testable', I2: 'Small', I3: 'Valuable' },
};

